mapper.select:
select id as id, topic_id as topicId, node_id as nodeId, address_name as addressName, longitude as longitude, latitude as latitude, address as address, pic_url as picUrl, (6371000 * acos(least(1, cos(radians(#{lat})) * cos(radians(cast(latitude as decimal(12,7)))) * cos(radians(cast(longitude as decimal(12,7))) - radians(#{lng})) + sin(radians(#{lat})) * sin(radians(cast(latitude as decimal(12,7)))) ))) as distance,
(select n.avatar from npc_profile n join mms_merchant m on m.id = n.scope_id where n.scope_type = 2 and m.member_id = cms_registration_merchant.member_id and m.del_flag = 0 and n.enabled = 1 and n.audit_status = 1 and n.del_flag = '0' order by n.sort asc, n.id asc limit 1) as npcAvatar,
(select t.product_type from cms_topic t where t.id = cms_registration_merchant.topic_id) as productType from cms_registration_merchant where del_flag = '0' and longitude is not null and longitude <> '' and latitude is not null and latitude <> '' and status = #{status} and audit_status = #{auditStatus} having distance <= #{radius} order by distance asc limit #{limit}
